class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price

    def apply_discount(self, percent):
        self.price = self.price * (1 - percent / 100)

    def display(self):
        print(f"{self.name}: ${self.price:.2f}")

item = Product("Laptop", 1000)
item.display()
item.apply_discount(20)
item.display()

