# Parent class
class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        print(f"{self.name} makes a sound")

# Child class inherits from Animal
class Dog(Animal):
    def speak(self):
        print(f"{self.name} barks: Woof!")

dog = Dog("Rex")
dog.speak()  # Rex barks: Woof!

class Vehicle:
    def __init__(self, brand):
        self.brand = brand

    def start(self):
        print(f"{self.brand} is starting...")

class Car(Vehicle):
    def __init__(self, brand, doors):
        super().__init__(brand)  # Call parent __init__
        self.doors = doors

my_car = Car("Toyota", 4)
my_car.start()  # Inherited method
print(my_car.doors)  # New attribute

class Bird(Animal):
    def speak(self):
        print(f"{self.name} chirps: Tweet!")

class Cat(Animal):
    def speak(self):
        print(f"{self.name} meows: Meow!")

bird = Bird("Tweety")
cat = Cat("Whiskers")

bird.speak()  # Tweety chirps: Tweet!
cat.speak()   # Whiskers meows: Meow!

class Fish(Animal):
    def swim(self):
        print(f"{self.name} is swimming")

fish = Fish("Nemo")
fish.speak()  # Inherited from Animal
fish.swim()   # New method specific to Fish

